const GITHUB_DATA_BASE="https://raw.githubusercontent.com/khs11235744-bit/indieplus-pohang/main/data/";
function dataStamp(data){
  if(!data)return 0;
  const raw=data.generatedAt||data.updated||"";
  if(!raw)return 0;
  const normalized=/ KST$/.test(raw)?raw.replace(" KST","+09:00").replace(" ","T"):raw;
  const t=Date.parse(normalized);
  return Number.isFinite(t)?t:0;
}
async function fetchGitHubData(url){
  try{
    const name=String(url).split("/").pop();
    if(!name)return null;
    const res=await fetch(GITHUB_DATA_BASE+name+"?v="+Date.now(),{cache:"no-store"});
    return res.ok?await res.json():null;
  }catch(e){
    console.warn("[INDIE GitHub] data fallback",url,e);
    return null;
  }
}
async function fetchCloudFirst(docId,url,required=true){
  const [cloud,github,hosted]=await Promise.all([
    fetchFirestorePublic(docId),
    fetchGitHubData(url),
    fetchJson(url,false).catch(()=>null)
  ]);
  const candidates=[cloud,github,hosted].filter(Boolean);
  if(candidates.length){
    candidates.sort((a,b)=>dataStamp(b)-dataStamp(a));
    return candidates[0];
  }
  if(required)throw new Error("No public data available: "+docId);
  return null;
}
window.fetchIndiePublicData=fetchCloudFirst;
